/** EIP-5792 call status codes.
 * Plus additional statuses for preconfirmations.
 *
 * Anything above a 200 is considered a terminal status.
 */
export const CallStatusCode = {
  /** Batch has been received by the wallet but has not completed execution onchain */
  PENDING: 100,
  /** Batch has been pre-confirmed onchain */
  PRECONFIRMED: 110,
  /** Batch reverted *completely* in a preconfirmation and only changes related to gas charge may have been included onchain */
  PRECONFIRMED_CHAIN_RULES_FAILURE: 115,
  /** Batch reverted *partially* in a preconfirmation and some changes related to gas charge may have been included onchain */
  PRECONFIRMED_PARTIAL_CHAIN_RULES_FAILURE: 116,
  /** Batch has been included onchain without reverts, receipts array contains info of all calls */
  CONFIRMED: 200,
  /** Batch has not been included onchain and wallet will not retry */
  OFFCHAIN_FAILURE: 400,
  /** Batch reverted *completely* and only changes related to gas charge may have been included onchain */
  CHAIN_RULES_FAILURE: 500,
  /** Batch reverted *partially* and some changes related to batch calls may have been included onchain */
  PARTIAL_CHAIN_RULES_FAILURE: 600,
  CROSS_CHAIN_IN_PROGRESS: 120,
  CROSS_CHAIN_REFUND: 410,
} as const;

/** EIP-5792 call status error codes. */
export const CallStatusErrorCode = {
  UNKNOWN_BUNDLE_ID: 5730,
};
